changeSet.sql:
CREATE UNIQUE INDEX IF NOT EXISTS uq_plan_version_name
    ON maintenance_plan_version (maintenance_plan_id, version_code);

CREATE UNIQUE INDEX IF NOT EXISTS uq_benefit_version_code
    ON plan_benefit (plan_version_id, benefit_code);

ALTER TABLE service_agreement
    ADD CONSTRAINT ck_service_agreement_window
    CHECK (ends_at IS NULL OR ends_at > starts_at);

ALTER TABLE plan_subscription
    ADD CONSTRAINT ck_plan_subscription_window
    CHECK (expires_at IS NULL OR activated_at IS NULL OR expires_at > activated_at);

ALTER TABLE maintenance_plan_version
    ADD CONSTRAINT ck_plan_version_amount
    CHECK (recurring_amount >= 0);
